INSERT INTO proizvodi_revidirana (id, primarni_id, izvor, naziv, brend, kategorija, cena, na_lageru, energetska_klasa, energetska_klasa_num, dijagonala_inch, kapacitet_kg, zapremina_l, snaga_w, sve_karakteristike, datum_preuzimanja) VALUES (3149, 6319, 'gigatron.rs', 'BOSCH PUE645BB5D Ugradna ploča', 'BOSCH', 'ugradna_rerna', '46499.00', TRUE, NULL, NULL, NULL, NULL, NULL, '3700.00', '{"18+": "No", "Boja": "Crna", "Vrsta": "Nezavisna", "Dubina": "51.3 cm", "Outlet": "No", "Vendor": "BSH KUCNI APARATI DOO", "Širina": "58.3 cm", "NAV Name": "Bosch PUE645BB5D ugr ploca", "sellerId": "1", "NAV Model": "PUE645BB5D", "Gigatron Id": "497633", "NAV Brand ID": "BOSCH", "NAV G-HYBRID": "No", "NAV Preorder": "No", "NAV Warranty": "Zakonska saobraznost 2 godine", "NAV Top Price": "No", "NAV Category ID": "UGRADNEPLO", "NAV Shock Price": "Yes", "Online kupovina": "Yes", "NAV Retail Price": "46499.000000", "Country of origin": "Španija", "NAV Price History": "40799.000000", "Priključna snaga": "3.700 W", "Način upravljanja": "Senzorsko upravljanje (na dodir)", "Sigurnosni sistemi": "<p>Digitalni dvostepeni indikator preostale toplote za svaku ploču za kuvanje: ukazuje na to koje su zone za kuvanje još uvek vruće ili tople</p> <p>Sigurnosna brava koja štiti decu: sprečava nenamerno aktiviranje ploče za kuvanje</p> <p>Glavni prekidač: isključuje sve zone za kuvanje jednostavnim dodirom dugmeta</p> <p>Sigurnosno isključivanje: iz bezbednosnih razloga, grejanje se zaustavlja nakon što istekne unapred podešeno vreme bez interakcije (prilagodljivo)</p> <p>PowerManagement funkcija: ograničite maksimalnu snagu ukoliko je to potrebno (u zavisnosti od zaštitnog osigurača na električnim instalacijama)</p>", "NAV Sticker Ends At": "2024-02-21 00:00:00", "NAV Salesperson Code": "DEJANL", "NAV Sticker Starts At": "2024-02-15 00:00:00", "Ugradne mere (ŠxVxD)": "56 x 5.5 x 49-50 cm", "NAV ERP Product Status": "4", "Ploče/zone za kuvanje": "<p>4 zone za kuvanje:</p> <p>Prednja leva: 180 mm, 1.8 kW (maksimalna snaga 3.1 kW)</p> <p>Zadnja leva: 180 mm, 1.8 kW (maksimalna snaga 3.1 kW)</p> <p>Zadnja desna: 145 mm, 1.4 kW (maksimalna snaga 2.2 kW)</p> <p>Prednja desna: 210 mm, 2.2 kW (maksimalna snaga 3.7 kW)</p>", "Vrsta ploče za kuvanje": "Indukciona", "Dimenzije ploče (ŠxVxD)": "58.3 x 5.5 x 51.3 cm", "Funkcije i karakteristike": "<p>Ugradnja sa okvirom</p> <p>Glavni materijal površine je keramika</p> <p>TouchSelect</p> <p>PowerBoost funkcija za sve ploče za kuvanje: voda će brže provreti zahvaljujući 20% više energije nego na najvišem standardnom nivou</p> <p>QuickStart funkcija: prilikom uključivanja, ploča za kuvanje automatski bira zonu za kuvanje na kojoj se nalazi posuđe (postavljeno u isključenom režimu)</p> <p>ReStart funkcija: u slučaju nenamernog isključivanja, vratite sva prethodna podešavanja ponovnim uključivanjem ploče za kuvanje u roku od 4 sekunde</p>", "NAV Category ID Description": "Ugradne ploče"}', '2026-06-21 02:58:48.649831');
