INSERT INTO proizvodi_revidirana (id, primarni_id, izvor, naziv, brend, kategorija, cena, na_lageru, energetska_klasa, energetska_klasa_num, dijagonala_inch, kapacitet_kg, zapremina_l, snaga_w, sve_karakteristike, datum_preuzimanja) VALUES (5361, 8922, 'gigatron.rs', 'MIDEA Rashladjivač vazduha AC100-18BR OUTLET', 'MIDEA', 'ventilator', '11199.00', FALSE, NULL, NULL, NULL, NULL, NULL, '50.00', '{"18+": "No", "Boja": "Bela", "Masa": "<p>6.6 kg</p>", "Snaga": "50 W", "Outlet": "Yes", "NAV Name": "OUT Midea AC100-18BR ventila", "sellerId": "1", "Dimenzije": "<p>ŠxVxD: 26.5 x 70 x 28 cm</p>", "NAV Model": "6939924827254", "NAV Brand ID": "MIDEA", "NAV G-HYBRID": "No", "NAV Preorder": "No", "NAV Warranty": "Zakonska saobraznost 1 godina", "NAV Top Price": "No", "Karakteristike": "<p>Air kuleri rade na principu hlađenja, isparavanjem vode. Prilikom duvanja toplog vazduha kroz vlažni medium u hladnjaku Air kulera, dolazi do isparavanja vode u kojem se vazduh hladi i tako rashlađen biva izduvan u okruženje. Što je veći rezervoar u Air kuleru to je veći kapacitet rashladjivanja. Radi intenzivnijeg hladjenja Air kuleri imaju mogućnost korišćenja leda.</p> <p>Oscilacija levo-desno</p> <p>3 brzine rada</p> <p>Zapremina vodenog tanka 5L</p> <p>Brzina isparavanja 500 ml/h</p>", "NAV Category ID": "VENTILATOR", "NAV Shock Price": "Yes", "Online kupovina": "No", "Long Description": "<p><strong>OPIS OUTLET PROIZVODA:</strong> Minimalni tragovi korišćenja. Uređaj dolazi sa 4 točka, daljinskim upravljačem i patronama. Pakovanje je u dobrom stanju, manji tragovi oštećenja. Za detaljnije informacije o stanju uređaja pozovite broj naše radnje G-06 - <span draggable=\"true\">011 848 0024</span>.</p>", "NAV Retail Price": "11199.00", "NAV Price History": "0.00", "NAV Salesperson Code": "IGORZ", "NAV ERP Product Status": "1", "NAV Category ID Description": "Ventilatori"}', '2026-06-21 03:09:02.029368');
